#!/usr/bin/env python3
"""Render the measured comparison, preserving every repetition in JSON."""
import html,json,pathlib,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1]
V=ROOT/'validation'
raw=json.loads((V/'comparison-raw.json').read_text())
pg=json.loads((V/'comparison-postgres.json').read_text())
assert raw.get('complete') and pg.get('complete'),'do not publish an unfinished benchmark'
for engine in ('zerofs','infinidisk2'):
    assert raw['tests'][engine+'-restored-256m-crc32c']=='passed'
    assert raw['tests'][engine+'-memory-warm']=='completed'
def n(x):return f'{x:,.0f}'.replace(',',' ')
def collect(engine,kind,side):
    samples=[raw['runs'][f'{engine}-{kind}-{i}'][side] for i in range(3)]
    return {'median':statistics.median(d['iops'] for d in samples),'min':min(d['iops'] for d in samples),'max':max(d['iops'] for d in samples),'p99_ms':statistics.median(d.get('clat_ns',{}).get('percentile',{}).get('99.000000',0)/1e6 for d in samples)}
cases=[('Lecture 4 Kio, cache initialement vide, SSD 128 Mio','cold-read','read'),('Lecture 4 Kio, SSD 512 Mio préchargé','warm-read','read'),('Écriture 4 Kio sans barrière par opération','buffered-write','write'),('Écriture 4 Kio + fsync local/S3 (garanties différentes)','fsync-write','write'),('Lecture séquentielle 1 Mio préchargée','seq-read','read')]
cases.extend([('Lecture 4 Kio, RAM 1 Gio préchargée','memory-warm-read','read'),('Lecture séquentielle 1 Mio, RAM 1 Gio','memory-warm-seq','read')])
summary={};rows=[];mdrows=[]
for label,kind,side in cases:
    z=collect('zerofs',kind,side);i=collect('infinidisk2',kind,side);ratio=i['median']/z['median']
    summary[kind]={'zerofs':z,'infinidisk2':i,'ratio':ratio}
    scale=1024**2 if kind in ('seq-read','memory-warm-seq') else 1
    unit='Mio/s' if scale!=1 else 'IOPS'
    def value(m):
        # Sequential requests are 1 MiB each, hence IOPS equals MiB/s.
        return f'{n(m["median"])} {unit} <small>({n(m["min"])}–{n(m["max"])})</small>'
    rows.append(f'<tr><td>{html.escape(label)}</td><td>{value(z)}</td><td>{value(i)}</td><td>×{ratio:.2f}</td><td>{z["p99_ms"]:.2f} / {i["p99_ms"]:.2f}</td></tr>')
    mdrows.append(f'| {label} | {n(z["median"])} {unit} | {n(i["median"])} {unit} | ×{ratio:.2f} |')
asyncm=collect('zerofs-async','fsync-write','write');summary['zerofs-ignore-fsync']=asyncm
pgm={e:statistics.median(s['tps'] for s in pg['postgres'][e]['samples']) for e in ('zerofs','infinidisk2')}
summary['postgres']=pgm
roomy={e:statistics.median(s['tps'] for s in pg['postgres'][e]['samples']) for e in ('zerofs-async-roomy','infinidisk2-roomy')}
for e in roomy:assert pg['postgres'][e]['database_SIGKILL_recovery']=='passed'
summary['postgres-roomy']=roomy
(V/'comparison-summary.json').write_text(json.dumps(summary,indent=2))
method='''Même VM partagée, même endpoint S3 https://storage.elestio.com et bucket testperf-6czebk, préfixes UUID distincts. ZeroFS 2.3.5, InfiniDisk2 0.1.0, Rust natif pour attacher les deux exports via 8 connexions TCP NBD, blocs Linux de 4 Kio. Volume 2 Gio, données fio 256 Mio, quatre jobs de profondeur 32 en aléatoire ; quatre jobs de profondeur 1 et fsync=1 en écriture synchrone. Trois échantillons de 15 secondes par cas, médiane et plage complète. Zone de lecture à 16 Mio ; écritures aléatoires à 512 Mio : les lectures portent sur un jeu stable et vérifié par CRC32c avant les autres charges. Mémoire configurée 64 Mio ; disque 128 Mio au démarrage froid, puis 512 Mio pour précharger le jeu de 256 Mio. InfiniDisk2 hot_wal_mib=0 ; ZeroFS compression lz4 et chiffrement applicatif, InfiniDisk2 sans compression ni chiffrement applicatif. Checkpoints/flush périodiques configurés à 5 secondes. Aucun drop_caches global. Aucun service préexistant modifié.'''
method+=' Passage complémentaire de lecture avec 1 Gio RAM et 4 Gio SSD sur les deux moteurs, jeu préchargé et trois répétitions. Après les restaurations, relecture intégrale des 256 Mio avec vérification CRC32c réussie sur les deux.'
limits='''Les lectures « froides » commencent avec un nouveau répertoire de cache, puis chauffent pendant l'échantillon ; ce n'est pas une mesure de 100 % de misses S3. Le SSD de 128 Mio reste inférieur au jeu de 256 Mio. Les couches de cache et leurs métadonnées diffèrent entre moteurs : budgets configurés égaux ne signifient pas RSS ou nombre de pages utiles égaux. La VM héberge d'autres services ; les moteurs sont testés successivement, ZeroFS puis InfiniDisk2, sans randomisation de l'ordre. Les variations S3 et la dégradation des écritures au fil des répétitions figurent dans les résultats bruts. Les données ne remplissent pas un grand volume, et chaque fenêtre est courte : ces résultats ne prouvent pas un débit soutenu de plusieurs heures, ni une capacité de production. Les appels directs évitent le cache Linux côté client ; ils ne suppriment pas tous les caches du serveur.'''
contracts='''InfiniDisk2 honore FLUSH/FUA sur le disque local, puis publie S3 de façon asynchrone. ZeroFS ignore_fsync=false publie vers S3 avant de terminer une barrière. Une perte du SSD juste après fsync peut donc perdre des transactions avec InfiniDisk2 ; cette fenêtre peut dépasser 5 secondes si S3 ralentit. Le ratio des écritures synchrones et de PostgreSQL compare ces deux contrats explicitement différents. ZeroFS ignore_fsync=true, utilisé par le wrapper précédent, ignore la barrière : son débit ne valide pas la durabilité d'une DB. Aucun test de ce rapport ne prouve l'absence absolue de corruption.'''
review=f'''Les chiffres rendent visibles les plafonds du chemin NBD/cache et le coût des barrières S3. Le débit synchrone ne permet pas de conclure qu'InfiniDisk2 est supérieur à contrat S3 identique : un comparateur qui force un checkpoint S3 à chaque FLUSH reste à mesurer. Le passage complémentaire ZeroFS sans fsync atteint {n(asyncm["median"])} IOPS (plage {n(asyncm["min"])}–{n(asyncm["max"])}), face à {n(summary["fsync-write"]["infinidisk2"]["median"])} IOPS avec barrière locale honorée par InfiniDisk2. Ce passage ZeroFS intervient après les lectures et chauffe une autre zone ; sa forte variation empêche d'attribuer son résultat au seul changement de ignore_fsync. Il ne reproduit pas nécessairement les chiffres du wrapper sur un autre jeu de données. Le gain en lecture doit être interprété à partir des p99 et des répétitions, pas du meilleur passage seul.'''
review+=f''' Avec les grands caches, PostgreSQL atteint {roomy["infinidisk2-roomy"]:.0f} TPS sur InfiniDisk2 contre {roomy["zerofs-async-roomy"]:.0f} TPS sur ZeroFS qui ignore fsync. Le prototype ne domine donc pas tous les cas : le débit des commits avec vraie synchronisation locale reste une priorité de développement.'''
recommendations='''Priorité 1 : conserver WAL et barrières locales, instrumenter le temps de synchronisation des segments et du watermark, puis réduire le nombre de barrières avec une preuve de récupération ; ne pas gagner des IOPS en ignorant fsync. Priorité 2 : tester PostgreSQL au-delà du cache, pendant plusieurs heures et sous coupures réseau, disque plein et panne VM ; vérifier pg_amcheck et sommes métier après chaque reprise. Priorité 3 : un cache SSD dimensionné pour le working set, avec préchargement ciblé et métriques de misses/p99. Priorité 4 : compaction des segments partiellement vivants, index paginé et visibilité du retard S3 ; sans cela les mesures sur 256 Mio ne représentent pas un gros disque. Garder un seul écrivain avec fencing externe pour takeover.'''
pgtext=f'''PostgreSQL 16 sous Docker, une CPU et 512 Mio, pgbench scale 2, quatre clients/quatre threads, trois fenêtres de 15 secondes. fsync, synchronous_commit, full_page_writes et data_checksums vérifiés actifs sur les deux. Médiane : ZeroFS {pgm["zerofs"]:.2f} TPS ; InfiniDisk2 {pgm["infinidisk2"]:.2f} TPS (×{pgm["infinidisk2"]/pgm["zerofs"]:.2f}). Aucune transaction échouée dans les échantillons. Après SIGKILL de PostgreSQL, redémarrage, égalité des sommes accounts/branches/tellers et pg_amcheck réussis sur les deux. Il s'agit d'un crash du processus DB ; les tests antérieurs distincts d'InfiniDisk2 couvrent aussi SIGKILL du moteur et restauration S3 seule. Ce petit jeu de données tient en cache ; ce n'est pas un benchmark de grande DB distante.'''
pgtext+=f''' Passage complémentaire sur les mêmes DB avec 1 Gio RAM et 4 Gio SSD pour chaque moteur : ZeroFS ignore_fsync=true {roomy["zerofs-async-roomy"]:.2f} TPS ; InfiniDisk2 avec fsync local honoré {roomy["infinidisk2-roomy"]:.2f} TPS (ratio {roomy["infinidisk2-roomy"]/roomy["zerofs-async-roomy"]:.2f}). PostgreSQL affiche toujours fsync=on, mais ZeroFS ignore sa demande dans ce passage : ce chiffre décrit un mode à durabilité relâchée. Le crash testé est celui de PostgreSQL pendant que le moteur de stockage reste actif ; son succès ne valide pas la reprise après perte du moteur ou de la VM avec fsync ignoré. Le rapport précédent du wrapper utilisait scale 100 et huit clients : ses 1 568 TPS ne sont pas directement comparables à notre scale 2/quatre clients/une CPU.'''
md=f'''# Comparaison mesurée : InfiniDisk2 / ZeroFS

{method}

| Charge | ZeroFS | InfiniDisk2 | Ratio |
|---|---:|---:|---:|
'''+ '\n'.join(mdrows)+f'''\n\n## Durabilité et interprétation\n\n{contracts}\n\n{review}\n\n## PostgreSQL\n\n{pgtext}\n\n## Limites\n\n{limits}\n\n## Recommandations\n\n{recommendations}\n\nRésultats complets : `../validation/comparison-raw.json`, `../validation/comparison-postgres.json`. Reproduction sur la VM : `python3 scripts/compare_zerofs.py`, puis `python3 scripts/compare_zerofs.py --postgres-only`. Le script utilise uniquement des volumes neufs dans des préfixes S3 UUID et les credentials privés existants ; il laisse les objets de test pour audit.\n'''
(ROOT/'docs/comparaison-zerofs.md').write_text(md)
phases=f'''\n\nLes phases complémentaires de cette exécution se reproduisent, moteurs arrêtés, avec :\n\n```sh\npython3 scripts/compare_zerofs.py --verify-report {raw['work']}/report.json\npython3 scripts/compare_zerofs.py --warm-memory-report {raw['work']}/report.json\npython3 scripts/compare_zerofs.py --postgres-roomy-report {pg['work']}/report.json\n```\n\nLes fichiers fio complets, logs et configurations sont conservés dans `../validation/comparison-artifacts/raw/` et `../validation/comparison-artifacts/postgres/`. Les empreintes binaires sont dans les JSON de synthèse d'exécution. Les exports excluent les credentials, WAL et caches ; les traces ont été contrôlées contre les secrets avant copie.\n'''
(ROOT/'docs/comparaison-zerofs.md').write_text(md+phases)
css='body{font:16px/1.6 system-ui;background:#eef2f6;color:#182637;margin:0}main{max-width:1120px;margin:auto;padding:32px}section{background:white;padding:24px;margin:20px 0;border-radius:12px}h1{line-height:1.2}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;border-bottom:1px solid #ddd;padding:10px}small{display:block;color:#607080}code{overflow-wrap:anywhere}a{color:#067}'
page=f'<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>InfiniDisk2 / ZeroFS — comparaison</title><style>{css}</style><main><h1>InfiniDisk2 / ZeroFS<br>Comparaison sur S3</h1><section><h2>Protocole</h2><p>{html.escape(method)}</p></section><section><h2>Médianes et plages des trois répétitions</h2><div style="overflow:auto"><table><tr><th>Charge</th><th>ZeroFS</th><th>InfiniDisk2</th><th>Ratio I/Z</th><th>p99 Z / I (ms)</th></tr>{"".join(rows)}</table></div><p>p99 médian de la latence de requête fio ; en écriture + fsync, la latence du syscall fsync est fournie séparément dans les JSON et ne doit pas être confondue avec celle de l’écriture.</p></section>'
for title,body in [('Contrats de durabilité',contracts),('Interprétation',review),('PostgreSQL et contrôle après crash',pgtext),('Limites de la mesure',limits),('Review et priorités',recommendations)]:page+=f'<section><h2>{title}</h2><p>{html.escape(body)}</p></section>'
page+='<section><h2>Résultats et reproduction</h2><p><a href="comparison-raw.json">Résultats fio complets</a> · <a href="comparison-postgres.json">PostgreSQL et validation</a> · <a href="comparison-summary.json">Synthèse numérique</a> · <a href="../scripts/compare_zerofs.py">Script de reproduction</a> · <a href="../docs/comparaison-zerofs.md">Rapport Markdown</a></p><p>Code et rapports : /opt/app/data/infinidisk2 ; VM : /root/infinidisk2.</p></section></main></html>'
(V/'comparaison-zerofs.html').write_text(page)
print(V/'comparaison-zerofs.html')
